import{_ as o,l as i,o as e,c as l,v as t,p,x as r,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"口令与加盐","description":"","frontmatter":{"title":"口令与加盐","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/password-salt.md","filePath":"cs/password-salt.md","lastUpdated":1789023840000}'),c={name:"cs/password-salt.md"};function E(m,a,A,_,u,f){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="口令与加盐" tabindex="-1">口令与加盐 <a class="header-anchor" href="#口令与加盐" aria-label="Permalink to &quot;口令与加盐&quot;">​</a></h1><div class="epigraph"><p>库里不存口令原文；盐让同一口令不再撞成同一串，慢哈希让离线猜测变贵。</p><footer>—— 据 Morris and Thompson, Password Security, CACM 1979；Anderson 对口令存储的整理</footer></div><p><a href="/cs/cert-revoke">上一课</a>用证书绑机器与服务身份。本课不重做 X.509。缺口是：人带着可记忆的秘密来证明自己。口令熵通常远低于密钥，且会被复用。存储必须假设库会被抄走——<a href="/cs/threat-model">威胁模型</a>里的「磁盘与备份在边界内仍可能泄露」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>明文存口令，一份泄露则全部身份作废。只做一次哈希，彩虹表与预计算把常用口令一次对上所有用户。缺口不是再讲<a href="/cs/hash-collision">哈希与碰撞</a>的抗碰撞，而是口令专用：每用户随机盐、慢哈希（或内存硬函数），使离线猜测按「每一猜测 × 每一用户」付钱。在线猜测另用限速与锁定，那是认证协议课。</p><p><span class="marginnote">盐不是保密材料，可与哈希一起存。胡椒（pepper）是服务器侧额外密钥，丢了则全体无法验证，本课只点名，不做成默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册：抽盐，存 \\((\\mathit{salt}, H(\\mathit{salt}\\|\\mathit{password}))\\) 或标准口令哈希 API 的输出。验证：用同一盐重算比较。禁止「可逆加密口令」当默认：那把保密重新绑到另一把主密钥上，主密钥一丢仍全军覆没。本课不讨论口令强度 UI，只锁定存储布局。</p>',8)),(e(),p(h,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PW%5B%22%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20SALT%5B%22%E6%AF%8F%E7%94%A8%E6%88%B7%E7%9B%90%22%5D%0A%20%20SALT%20--%3E%20SH%5B%22%E6%85%A2%E5%93%88%E5%B8%8C%22%5D%0A%20%20SH%20--%3E%20STORE%5B%22%E5%AD%98%E7%9B%90%E4%B8%8E%E6%91%98%E8%A6%81%22%5D%0A%20%20STORE%20--%3E%20AUTH%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%AE%A4%E8%AF%81%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>盐打碎预计算表；慢哈希（迭代、内存困难）把 GPU 穷举的速率压下来。这不把弱口令变成密钥：在线与针对性猜测仍成立。完整轴：口令哈希不提供对会话的认证，只服务「核验人记得的秘密」。传输中口令必须走已认证的保密信道，否则盐与哈希都是事后。</p><p>同一口令在不同盐下摘要不同，泄漏一份哈希不能直接对上另一用户。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把加盐写成「加密」。不要给具体破解步骤或词表攻击配方。本课也不把生物特征、硬件令牌写进存储格式。恢复流程（邮件重置）往往比哈希更弱，属于协议与运营，下一课会碰到认证的消息顺序。</p><p>口令复用使一次泄露变成多站身份事故；这是人的熵与威胁模型问题，不是盐算错。后课默认：口令核验针对盐化慢哈希；如何证明「我是这个用户」的消息往返，是认证协议。</p><p>传输中的口令必须走已认证保密信道。盐化存储保护的是盘上的抄本，不是线路上的明文。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>离线猜测的代价由慢哈希与盐共同决定；在线猜测要限速，属下一课协议。</p></li><li><p>可逆「加密存口令」把全部身份绑到主密钥，本课不当默认。</p></li><li><p>证书绑服务；本课把人的秘密存成盐化慢哈希，假设库会泄露。</p></li><li><p>盐破预计算；慢哈希抬离线代价；弱口令仍弱。</p></li><li><p>核验之后如何建会话、防重放，是认证协议缺口。</p></li><li><p>出处：Morris and Thompson, 1979；Anderson, <em>Security Engineering</em>。</p></li></ul>',9))])}const B=o(c,[["render",E]]);export{S as __pageData,B as default};
